/**
 * Google Gemini Node - Version 1
 * Discriminator: resource=image, operation=generate
 */


interface Credentials {
  googlePalmApi: CredentialReference;
}

/** Creates an image from a text prompt */
export type LcGoogleGeminiV1ImageGenerateParams = {
  resource: 'image';
  operation: 'generate';
/**
 * Model
 * @searchListMethod imageGenerationModelSearch
 * @default {"mode":"list","value":""}
 */
    modelId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * A text description of the desired image(s)
 */
    prompt?: string | Expression<string>;
/**
 * Options
 * @default {}
 */
    options?: {
    /** Number of images to generate
     * @displayOptions.show { /modelId: [{"_cnd":{"includes":"imagen"}}] }
     * @default 1
     */
    sampleCount?: number | Expression<number>;
    /** Put Output in Field
     * @hint The name of the output field to put the binary file data in
     * @default data
     */
    binaryPropertyOutput?: string | Expression<string>;
  };
};

export interface LcGoogleGeminiV1ImageGenerateSubnodeConfig {
  tools?: ToolInstance[];
}

export type LcGoogleGeminiV1ImageGenerateNode = {
  type: '@n8n/n8n-nodes-langchain.googleGemini';
  version: 1;
  isTrigger: true;
  config: NodeConfig<LcGoogleGeminiV1ImageGenerateParams> & { credentials?: Credentials } & { subnodes?: LcGoogleGeminiV1ImageGenerateSubnodeConfig };
};